import json
import subprocess
import sys

from decimal import Decimal, localcontext, ROUND_HALF_EVEN

sys.path.insert(0, ".")
from urban_micro import panel_report, portfolio_attribution  # noqa: E402


def attribution_report(items, total_weight=1.0, alpha=0.05):
    """Build a canonical portfolio_attribution JSON string by hand."""
    parts = []
    for key, n, expected, worst, sensitivity, p, q, reject in items:
        parts.append(
            '{"key":' + json.dumps(key, ensure_ascii=False)
            + f',"n":{n},"expected":{expected:.6f},"worst":{worst:.6f},'
            + f'"sensitivity":{sensitivity:.6f},"p":{p:.6f},"q":{q:.6f},'
            + ('"reject":true}' if reject else '"reject":false}')
        )
    return (
        f'{{"alpha":{alpha:.6f},"total_weight":{total_weight:.6f},'
        + '"items":[' + ",".join(parts) + "]}\n"
    )


# 4 panels: regions r1/r2 x windows w1/w2; 3 candidates a,b,c.
def items_for(vals):
    # vals: dict candidate -> (expected, reject)
    out = []
    for key in sorted(vals):
        v, rj = vals[key]
        out.append((key, 2, v, v, 0.0, 0.5, 0.5, rj))
    return out


panels = [
    ("r1", "w1"),
    ("r1", "w2"),
    ("r2", "w1"),
    ("r2", "w2"),
]
data = {
    ("r1", "w1"): {"a": (1.0, True), "b": (0.0, False), "c": (0.3, False)},
    ("r1", "w2"): {"a": (1.0, True), "b": (0.0, False), "c": (0.2, False)},
    ("r2", "w1"): {"a": (0.0, False), "b": (1.0, True), "c": (0.4, False)},
    ("r2", "w2"): {"a": (0.0, False), "b": (1.0, True), "c": (0.2, False)},
}
reports = {k: attribution_report(items_for(v)) for k, v in data.items()}
weights = {k: 1.0 for k in panels}

out = panel_report(reports, weights)
print(out)

parsed = json.loads(out)
assert out.endswith("\n") and not out.endswith("\n\n")
assert list(parsed) == ["alpha", "groups"]
assert [g["by"] for g in parsed["groups"]] == [
    "region", "region", "window", "window", "overall"
]
assert [g["key"] for g in parsed["groups"]] == [
    "r1", "r2", "w1", "w2", "all"
]
for g in parsed["groups"]:
    assert list(g) == ["by", "key", "items"]
    assert [it["key"] for it in g["items"]] == ["a", "b", "c"]
    for it in g["items"]:
        assert list(it) == [
            "key", "n", "mean", "range", "stable", "p", "q", "reject"
        ]
        assert isinstance(it["n"], int)
        assert isinstance(it["reject"], bool)
print("structure OK")

# Manual checks for candidate a in overall group.
# values [1,1,0,0], weights 1: mean .5, range 1, stable .5
overall = parsed["groups"][-1]
it_a = next(i for i in overall["items"] if i["key"] == "a")
assert it_a["n"] == 4
assert it_a["mean"] == 0.5
assert it_a["range"] == 1.0
assert it_a["stable"] == 0.5
# sign stats: |s1+s2| >= 2 (threshold = |sum terms| = 2). 2 sign combos /16
assert it_a["p"] == 0.125, it_a
# candidate b in region r2: values [0,1] mean .5, range 1, stable 1
r2 = parsed["groups"][1]
it_b = next(i for i in r2["items"] if i["key"] == "b")
assert it_b["n"] == 2 and it_b["mean"] == 0.5 and it_b["range"] == 1.0
assert it_b["stable"] == 1.0 and it_b["p"] == 0.5
print("stats OK")

# n<=16 violation: 17 panels
big = {}
for i in range(17):
    big[(f"r{i % 5}", f"w{i}")] = reports[panles0] if False else reports[panels[0]]
try:
    panel_report(big, {k: 1.0 for k in big})
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError for 17 panels")

# TypeError checks
for bad_reports, bad_weights in [("x", weights), (reports, "x")]:
    try:
        panel_report(bad_reports, bad_weights)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError")

# Single panel -> ValueError
try:
    panel_report({panels[0]: reports[panels[0]]}, {panels[0]: 1.0})
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError for one panel")

# weight mismatch / non-positive
try:
    panel_report(reports, {panels[0]: 1.0})
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError on weight key mismatch")
bad_w = dict(weights)
bad_w[panels[0]] = 0.0
try:
    panel_report(reports, bad_w)
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError on zero weight")

# bool weight
try:
    panel_report(reports, {**weights, panels[0]: True})
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError on bool weight")

# bad key shape
try:
    panel_report({"x": reports[panels[0]]}, {"x": 1.0})
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError on bad key")

# candidate mismatch
bad_reports = dict(reports)
bad_reports[panels[0]] = attribution_report(
    items_for({"a": (1.0, True), "b": (0.0, False)})
)
try:
    panel_report(bad_reports, weights)
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError on candidate mismatch")

# tampered report (missing trailing newline)
tampered = dict(reports)
tampered[panels[0]] = tampered[panels[0]].rstrip("\n")
try:
    panel_report(tampered, weights)
except ValueError:
    pass
else:
    raise AssertionError("expected ValueError on tampered report")

# alpha validation
for bad_alpha in (0.0, 1.5, True, "0.05", float("nan")):
    try:
        panel_report(reports, weights, alpha=bad_alpha)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for alpha={bad_alpha!r}")

# alpha=1 accepted
panel_report(reports, weights, alpha=1)
print("validation OK")

# Unicode preserved
uni_reports = {
    ("地区1", "窗1"): attribution_report(
        [("候选α", 2, 0.5, 0.5, 0.0, 0.5, 0.5, True)]
    ),
    ("地区1", "窗2"): attribution_report(
        [("候选α", 2, 0.5, 0.5, 0.0, 0.5, 0.5, False)]
    ),
}
uni_out = panel_report(uni_reports, {k: 1.0 for k in uni_reports})
assert "地区1" in uni_out and "候选α" in uni_out
json.loads(uni_out)
print("unicode OK")

# negative zero normalization: mean 0 when values all zero -> 0.000000 not -0
zero_reports = {
    ("r1", "w1"): attribution_report(
        [("z", 2, 0.0, 0.0, 0.0, 1.0, 1.0, False)]
    ),
    ("r1", "w2"): attribution_report(
        [("z", 2, 0.0, 0.0, 0.0, 1.0, 1.0, False)]
    ),
}
zo = panel_report(zero_reports, {("r1", "w1"): 1.0, ("r1", "w2"): 1.0})
assert '"mean":0.000000' in zo and "-0.000000" not in zo
print("negative zero OK")

# Cross-check p-values against an independent Fraction computation.
from fractions import Fraction
rng_data = {
    ("r1", "w1"): {"a": (0.7, True), "b": (0.1, False)},
    ("r1", "w2"): {"a": (0.2, False), "b": (0.9, True)},
    ("r2", "w1"): {"a": (0.5, False), "b": (0.3, False)},
}
r_reports = {
    k: attribution_report(items_for(v)) for k, v in rng_data.items()
}
r_weights = {("r1", "w1"): 1.5, ("r1", "w2"): 2.0, ("r2", "w1"): 0.5}
ro = json.loads(panel_report(r_reports, r_weights))
for g in ro["groups"]:
    members = [k for k in rng_data if (
        g["by"] == "overall"
        or (g["by"] == "region" and k[0] == g["key"])
        or (g["by"] == "window" and k[1] == g["key"])
    )]
    w = [Fraction(str(r_weights[k])) for k in members]
    for it in g["items"]:
        v = [Fraction(str(rng_data[k][it["key"]][0])) for k in members]
        n = len(members)
        W = sum(w)
        mean = sum(wi * vi for wi, vi in zip(w, v)) / W
        rng = max(v) - min(v)
        hits = 0
        total = sum(wi * vi for wi, vi in zip(w, v))
        for mask in range(1 << n):
            s = sum(
                (wi * vi if mask >> k & 1 else -wi * vi)
                for k, (wi, vi) in enumerate(zip(w, v))
            )
            if abs(s) >= abs(total):
                hits += 1
        p = Fraction(hits, 1 << n)
        assert abs(float(mean) - it["mean"]) < 1e-9, (g["key"], it)
        assert abs(float(rng) - it["range"]) < 1e-9
        assert abs(float(p) - it["p"]) < 1e-9
print("independent p-value cross-check OK")

# BH q check on the pooled set for the random case: recompute manually.
all_p = []
for gi, g in enumerate(ro["groups"]):
    for it in g["items"]:
        all_p.append((it["p"], gi, g["key"], it["key"], it["q"], it["reject"]))
N = len(all_p)
ranked = sorted(all_p, key=lambda t: (t[0], t[1], t[2], t[3]))
run = 1.0
for rank in range(N, 0, -1):
    cand = min(1.0, N * ranked[rank - 1][0] / rank)
    run = min(run, cand)
    assert abs(run - ranked[rank - 1][4]) < 1e-9, ranked[rank - 1]
print("BH q cross-check OK")

# CLI unchanged
ver = subprocess.run(
    [sys.executable, "-m", "urban_micro.cli", "version"],
    capture_output=True, text=True, check=True,
)
assert ver.stdout.strip() == "0.1.0"
print("ALL OK")

