}
r_weights = {("r1", "w1"): 1.5, ("r1", "w2"): 2.0, ("r2", "w1"): 0.5}
ro = json.loads(panel_report(r_reports, r_weights))
for g in ro["groups"]:
    members = [k for k in rng_data if (
        g["by"] == "overall"
        or (g["by"] == "region" and k[0] == g["key"])
        or (g["by"] == "window" and k[1] == g["key"])
    )]
    w = [Fraction(str(r_weights[k])) for k in members]
    for it in g["items"]:
        v = [Fraction(str(rng_data[k][it["key"]][0])) for k in members]
        n = len(members)
        W = sum(w)
        mean = sum(wi * vi for wi, vi in zip(w, v)) / W
        rng = max(v) - min(v)
        hits = 0
        total = sum(wi * vi for wi, vi in zip(w, v))
        for mask in range(1 << n):
            s = sum(
                (wi * vi if mask >> k & 1 else -wi * vi)
                for k, (wi, vi) in enumerate(zip(w, v))
            )
            if abs(s) >= abs(total):
                hits += 1
        p = Fraction(hits, 1 << n)
        assert abs(float(mean) - it["mean"]) < 1e-9, (g["key"], it)
        assert abs(float(rng) - it["range"]) < 1e-9
        assert abs(float(p) - it["p"]) < 1e-9
print("independent p-value cross-check OK")

